const dfloat=s=>Math.round(Number(s)*10)/10;
const hav=(a,b)=>{const rad=Math.PI/180,p1=a.lat*rad,p2=b.lat*rad,dLat=(b.lat-a.lat)*rad,dLon=(b.lng-a.lng)*rad,q=Math.sin(dLat/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dLon/2)**2;return 6371*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q))};
const dateLabel=d=>new Date(d+'T12:00:00+05:30').toLocaleDateString('en-IN',{day:'2-digit',month:'short',weekday:'short'});
const baseStops=DATA.stops.map((x,i)=>({...x,id:'seed-'+i,station:({tvc:'TVC',ncj:'NCJ',var:'BSB',agr:'AGC',dli:'NDLS',jai:'JP',jsm:'JSM',ddn:'DDN',snk:'DDN',jat:'JAT',sina:'SINA',gul:'SINA'})[x.key]||''}));
let lastGpsRoadAt=0,routeAllowed=false;
let stops=read('destinations',baseStops), activities=read('activities',[]),bookings=read('bookings',[]),ideas=read('ideas',[]),journal=read('journal',[]),packing=read('packing',null||[]),payments=read('payments',[]),emergency=read('emergency',{name:'',phone:''}),lastLocation=null,watchID=null,routeMap=null,locationMarker=null,previewLayers=[],routeDistances=read('roadDistances',{});
const saveStops=()=>{write('destinations',stops);drawDestinations();drawLegs();drawSelectors();drawMap();drawCoach();};
const saveActivities=()=>{write('activities',activities);drawHours();drawCustomActivities();drawCoach()};
const saveBookings=()=>{write('bookings',bookings);drawBookings();drawCoach()};
const dateOptions=()=>DATA.days.map(x=>`<option value="${h(x.date)}">${h(dateLabel(x.date))} · ${h(x.title)}</option>`).join('');
function onBoard(id){const el=$('#'+id);if(el&&el.value){} }
// Dashboard day editor: baseline 4 x 6-hour windows; each hour explicitly scheduled.
function baseBlock(date,hour){let d=DATA.days.find(x=>x.date===date);return d?.blocks[Math.min(3,Math.floor(hour/6))]||{text:'Open time · rest, travel buffer or your own activity',type:'rest'};}
function drawHours(){const date=$('#v2-day')?.value;if(!date)return;$('#v2-act-date').value=date;const now=new Date(),today=dateNow();$('#v2-hours').innerHTML=Array.from({length:24},(_,hh)=>{const time=String(hh).padStart(2,'0')+':00',item=activities.find(x=>x.date===date&&Number(x.start.slice(0,2))<=hh&&Number(x.end.slice(0,2))>hh),orig=baseBlock(date,hh),tx=item?item.title:orig.text,kind=item?.kind||orig.type;return `<div class="v2-hour ${today===date&&now.getHours()===hh?'current':''}"><time>${time}</time><div class="${h(kind)}"><b>${item? '★ ':''}${h(tx)}</b>${item?.notes?'<small class="v2-muted"> · '+h(item.notes)+'</small>':''}</div></div>`}).join('');drawCustomActivities();}
function drawCustomActivities(){const date=$('#v2-day')?.value;$('#v2-custom-acts').innerHTML=activities.filter(a=>a.date===date).sort((a,b)=>a.start.localeCompare(b.start)).map(a=>`<div class="v2-item v2-between"><div><strong>${h(a.start)}–${h(a.end)}</strong> ${h(a.title)}<div class="v2-tiny">${h(a.kind)} · ${h(a.notes)}</div></div><div class="v2-row"><button class="v2-toolbtn" data-v2-edit-act="${h(a.id)}">Edit</button><button class="v2-toolbtn" data-v2-del-act="${h(a.id)}">×</button></div></div>`).join('')||'<p class="v2-muted">Use the form above to add precise appointments. The original four time blocks fill unassigned hours.</p>'}
function activityReset(){ $('#v2-activity-form').reset();$('#v2-act-id').value='';$('#v2-act-date').value=$('#v2-day').value;}
$('#v2-day').innerHTML=dateOptions();$('#v2-day').value='2027-01-23';$('#v2-day').addEventListener('change',drawHours);$('#v2-today').onclick=()=>{$('#v2-day').value=DATA.days.some(d=>d.date===dateNow())?dateNow():'2027-01-23';drawHours()};$('#v2-print').onclick=()=>window.print();$('#v2-act-clear').onclick=activityReset;
$('#v2-activity-form').addEventListener('submit',e=>{e.preventDefault();let obj={id:$('#v2-act-id').value||uid(),date:$('#v2-act-date').value,start:$('#v2-act-start').value,end:$('#v2-act-end').value,kind:$('#v2-act-kind').value,title:$('#v2-act-title').value.trim(),notes:$('#v2-act-notes').value.trim()};if(!obj.start||!obj.end||obj.start>=obj.end)return notify('End time must be after start time on the same day.');if(!DATA.days.some(d=>d.date===obj.date))return notify('Choose a date within the trip.');activities=activities.filter(x=>x.id!==obj.id);activities.push(obj);$('#v2-day').value=obj.date;saveActivities();activityReset();notify('Hourly activity saved.')});
document.addEventListener('click',e=>{const edit=e.target.closest('[data-v2-edit-act]'),del=e.target.closest('[data-v2-del-act]');if(edit){let a=activities.find(x=>x.id===edit.dataset.v2EditAct);if(!a)return;$('#v2-act-id').value=a.id;$('#v2-act-date').value=a.date;$('#v2-act-start').value=a.start;$('#v2-act-end').value=a.end;$('#v2-act-kind').value=a.kind;$('#v2-act-title').value=a.title;$('#v2-act-notes').value=a.notes;$('#v2-act-title').focus()}if(del&&confirm('Remove this activity?')){activities=activities.filter(a=>a.id!==del.dataset.v2DelAct);saveActivities()}});
// User editable destination list: original destinations are safe to reorder but not silently rewritten.
function drawDestinations(){$('#v2-dest-list').innerHTML=stops.map((s,i)=>`<div class="v2-item v2-between"><div><span class="v2-tag">${i+1}</span> <b>${h(s.name)}</b><small class="v2-muted"> ${h(s.date)} · ${h(s.station||'Road-only')}</small><div class="v2-tiny">${h(s.note)}</div></div><div class="v2-row"><button class="v2-toolbtn" data-v2-move="${h(s.id)}" data-move-dir="-1" title="Move earlier">↑</button><button class="v2-toolbtn" data-v2-move="${h(s.id)}" data-move-dir="1" title="Move later">↓</button><button class="v2-toolbtn" data-v2-dest-edit="${h(s.id)}">Edit</button>${s.id.startsWith('seed-')?'':`<button class="v2-toolbtn" data-v2-dest-remove="${h(s.id)}">×</button>`}</div></div>`).join('')}
function drawSelectors(){let sel=$('#v2-select-next'),val=sel.value;sel.innerHTML=stops.map((x,i)=>`<option value="${i}">${i+1}. ${h(x.name)} (${h(x.date)})</option>`).join('');if(val!==''&&Number(val)<stops.length)sel.value=val;else sel.value=String(Math.min(13,stops.length-1));const i=Number(sel.value),s=stops[i];$('#v2-next').textContent=s?.name||'No stop selected';$('#v2-next-distance').textContent=lastLocation?Math.round(hav(lastLocation,s))+' km straight-line minimum to destination':'Allow GPS or select two route stops';$('#v2-train-to').value=s.station||'';const closest=lastLocation?stops.filter(x=>x.station).map(x=>({x,d:hav(lastLocation,x)})).sort((a,b)=>a.d-b.d)[0]:null;$('#v2-train-from').value=(closest&&closest.d<40?closest.x.station:stops[Math.max(0,i-1)]?.station)||'';$('#v2-train-date').value=s.date;}
let editDestination=null;
$('#v2-add-dest').onsubmit=e=>{e.preventDefault();let name=$('#v2-place-name').value.trim(),lat=Number($('#v2-place-lat').value),lng=Number($('#v2-place-lng').value);if(!name||$('#v2-place-lat').value===''||$('#v2-place-lng').value===''||!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)return notify('Enter valid latitude and longitude. Use Find coordinates.');const obj={id:editDestination||uid(),name,date:$('#v2-place-date').value,lat,lng,station:$('#v2-place-code').value.trim().toUpperCase(),note:$('#v2-place-notes').value.trim()||'Added on the go',type:'city',key:'custom'};if(editDestination){stops=stops.map(s=>s.id===editDestination?obj:s)}else{let insertAt=stops.findIndex(s=>s.date>obj.date);if(insertAt===-1)insertAt=stops.length;stops.splice(insertAt,0,obj)}editDestination=null;$('#v2-add-dest').reset();saveStops();notify('Destination updated. Recheck train connections.');};
$('#v2-find-place').onclick=async()=>{let q=$('#v2-place-name').value.trim();if(!q)return notify('Enter a place name first.');$('#v2-geocode-status').textContent='Searching place coordinates…';try{const u=new URL('https://photon.komoot.io/api/');u.searchParams.set('q',q+', India');u.searchParams.set('limit','1');const resp=await fetch(u,{signal:AbortSignal.timeout(12000)});if(!resp.ok)throw Error('Search unavailable');const j=await resp.json(),f=j.features?.[0];if(!f)throw Error('No match — try city and state');$('#v2-place-lng').value=f.geometry.coordinates[0];$('#v2-place-lat').value=f.geometry.coordinates[1];$('#v2-geocode-status').textContent='Match: '+[f.properties.name,f.properties.city,f.properties.state].filter(Boolean).join(', ')+' — check before saving.';}catch(err){$('#v2-geocode-status').textContent=err.message+'; enter coordinates manually.'}};
$('#v2-place-gps').onclick=()=>{if(!lastLocation)return notify('Start live GPS first to use current coordinates.');$('#v2-place-lat').value=lastLocation.lat;$('#v2-place-lng').value=lastLocation.lng};
document.addEventListener('click',e=>{let mv=e.target.closest('[data-v2-move]');if(mv){let i=stops.findIndex(s=>s.id===mv.dataset.v2Move),j=i+Number(mv.dataset.moveDir);if(i>=0&&j>=0&&j<stops.length){[stops[i],stops[j]]=[stops[j],stops[i]];saveStops()}}let ed=e.target.closest('[data-v2-dest-edit]');if(ed){let s=stops.find(x=>x.id===ed.dataset.v2DestEdit);if(!s)return;editDestination=s.id;$('#v2-place-name').value=s.name;$('#v2-place-date').value=s.date;$('#v2-place-lat').value=s.lat;$('#v2-place-lng').value=s.lng;$('#v2-place-code').value=s.station||'';$('#v2-place-notes').value=s.note||'';$('#v2-place-name').focus()}let rm=e.target.closest('[data-v2-dest-remove]');if(rm&&confirm('Remove this custom destination?')){stops=stops.filter(s=>s.id!==rm.dataset.v2DestRemove);saveStops()}});
// Map and GPS. All position updates stay client-side unless user manually copies the location.
function drawMap(){if(typeof L==='undefined'){$('#v2-route-map').innerHTML='<p style="padding:30px">Online maps are temporarily unavailable. Your destination list remains accessible.</p>';return}if(!routeMap){routeMap=L.map('v2-route-map',{scrollWheelZoom:false});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:18}).addTo(routeMap)}previewLayers.forEach(l=>routeMap.removeLayer(l));previewLayers=[];let pts=stops.filter(s=>Number.isFinite(Number(s.lat))&&Number.isFinite(Number(s.lng))).map(s=>[+s.lat,+s.lng]);if(!pts.length)return;let line=L.polyline(pts,{weight:4,color:'#b8e16f',opacity:.7,dashArray:'7,8'}).addTo(routeMap);previewLayers.push(line);stops.forEach((s,i)=>{let m=L.marker([s.lat,s.lng],{icon:L.divIcon({className:'',html:`<div class="pin-route"><span>${i+1}</span></div>`,iconSize:[29,29],iconAnchor:[14,27]})}).addTo(routeMap).bindPopup(`<b>${i+1}. ${h(s.name)}</b><br>${h(s.date)}<br>${h(s.note)}<br><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.lat+','+s.lng)}">Open Google Maps</a>`);previewLayers.push(m)});routeMap.fitBounds(line.getBounds().pad(.13));if(lastLocation)updateGPSMap()}
function updateGPSMap(){if(!routeMap||!lastLocation||typeof L==='undefined')return;if(!locationMarker)locationMarker=L.circleMarker([lastLocation.lat,lastLocation.lng],{color:'#fff',fillColor:'#00c4ed',fillOpacity:1,weight:3,radius:10}).addTo(routeMap);else locationMarker.setLatLng([lastLocation.lat,lastLocation.lng]);$('#v2-coords').textContent=lastLocation.lat.toFixed(5)+', '+lastLocation.lng.toFixed(5);$('#v2-gps-detail').textContent='Accuracy ±'+Math.round(lastLocation.accuracy)+' m · '+new Date(lastLocation.t).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata'});drawSelectors();if(routeAllowed&&Date.now()-lastGpsRoadAt>90000){lastGpsRoadAt=Date.now();requestRoadFromGPS()}}
const enableGPS=()=>{if(!navigator.geolocation||!window.isSecureContext){notify('GPS needs HTTPS, a supported browser and location permission.');return}if(watchID!==null)return notify('GPS is already running');watchID=navigator.geolocation.watchPosition(p=>{lastLocation={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,t:Date.now()};updateGPSMap()},e=>{notify('Location unavailable: '+e.message);if(watchID!==null){navigator.geolocation.clearWatch(watchID);watchID=null}},{enableHighAccuracy:true,maximumAge:8000,timeout:20000})};
$('#v2-gps-start').onclick=enableGPS;$('#v2-gps-stop').onclick=()=>{if(watchID!==null)navigator.geolocation.clearWatch(watchID);watchID=null;$('#v2-coords').textContent='GPS paused';};$('#v2-gps-center').onclick=()=>{if(lastLocation&&routeMap)routeMap.setView([lastLocation.lat,lastLocation.lng],13);else notify('Start GPS first')};
window.addEventListener('beforeunload',()=>{if(watchID!==null)navigator.geolocation.clearWatch(watchID)});
$('#v2-select-next').addEventListener('change',()=>{drawSelectors();if(routeAllowed)requestRoadFromGPS()});
$('#v2-road-optin').onclick=()=>{if(!lastLocation)return notify('Start GPS first.');routeAllowed=true;lastGpsRoadAt=Date.now();requestRoadFromGPS();};
function googLink(start,end){const origin=start?`${start.lat},${start.lng}`:'';return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(end.lat+','+end.lng)+'&travelmode=driving'+(origin?'&origin='+encodeURIComponent(origin):'')}
$('#v2-directions').onclick=()=>{let s=stops[Number($('#v2-select-next').value)];if(s)window.open(googLink(lastLocation,s),'_blank','noopener,noreferrer')};
async function requestRoad(a,b){let k=a.lat.toFixed(3)+','+a.lng.toFixed(3)+'~'+b.lat.toFixed(3)+','+b.lng.toFixed(3);let value=routeDistances[k];if(value&&Date.now()-value.at<7*86400000)return value;let u='/api/road?from='+encodeURIComponent(a.lng+','+a.lat)+'&to='+encodeURIComponent(b.lng+','+b.lat);const response=await fetch(u,{signal:AbortSignal.timeout(15000)});const j=await response.json();if(!response.ok||!j.distanceKm)throw Error(j.error||'Road routing unavailable');value={...j,at:Date.now()};routeDistances[k]=value;write('roadDistances',routeDistances);return value;}
async function requestRoadFromGPS(){let s=stops[Number($('#v2-select-next').value)];if(!s)return;if(!lastLocation){$('#v2-route-result').textContent='GPS not enabled';$('#v2-route-hint').textContent='Use Start GPS for distance from current position.';return}let crow=dfloat(hav(lastLocation,s));$('#v2-next-distance').textContent=crow+' km straight line (minimum)';$('#v2-route-result').textContent='Calculating…';try{let r=await requestRoad(lastLocation,s);$('#v2-route-result').textContent=dfloat(r.distanceKm)+' km · '+Math.round(r.durationMin)+' min';$('#v2-route-hint').textContent=(r.provider||'Road router')+' estimated road route; weather and traffic not accounted for';}catch(err){$('#v2-route-result').textContent=crow+' km straight line';$('#v2-route-hint').textContent='Road time unavailable ('+err.message+'); no travel ETA has been invented.'}}
const planLegDurations={ 'ncj-var':'Train 16367 · ~50 h 30 m', 'var-agr':'Train 12206 · ~11 h 10 m', 'agr-dli':'Train 12279 · ~3 h 05 m','dli-jai':'Train 19702 · ~8 h 23 m','jai-jsm':'Train 12468 · ~12 h 40 m','dli-ddn':'Train 12401 · ~6 h', 'jat-sina':'Vande Bharat 26401 · ~4 h 50 m','sina-gul':'Winter road · allow 2–4+ h','ddn-snk':'Trek vehicle · allow 8–11+ h','snk-ddn':'Trek return · 8–11+ h','dli-tvc':'Train 12626 · ~49 h 40 m', 'jsm-dli':'Via Jaipur by rail · ~28 h 20 m incl. transfer', 'ddn-jat':'Via Delhi by rail · ~30 h incl. long layover', 'gul-dli':'Via Srinagar and Jammu · ~24–30+ h' };
function drawLegs(){const tbody=$('#v2-route-legs');tbody.innerHTML=stops.slice(1).map((s,n)=>{let a=stops[n],key=a.key+'-'+s.key,d=dfloat(hav(a,s)),travel=planLegDurations[key]||((['snk','gul'].includes(a.key)||['snk','gul'].includes(s.key))?'Road transfer · winter-dependent':'Travel mode/time: verify train timetable'),kmLabel=`${d} km minimum direct distance`;return `<tr><td>${n+1}</td><td><b>${h(a.name)} → ${h(s.name)}</b><small>${h(a.station||'Road')} → ${h(s.station||'Road')}</small></td><td>${h(dateLabel(s.date))}</td><td id="v2-km-${n}">${kmLabel}</td><td>${h(travel)}<small>Planned, not live</small></td><td><button class="v2-toolbtn" data-v2-road="${n}">Road km</button> <button class="v2-toolbtn" data-v2-choose="${n+1}">Select</button></td></tr>`}).join('')}
$('#v2-recalc-legs').onclick=async()=>{notify('Calculating selected short road transfers. Long rail segments remain timetable-based.');const indices=stops.slice(1).map((s,i)=>({i,d:hav(stops[i],s)})).filter(x=>x.d<350).slice(0,10);for(const {i} of indices){let td=$('#v2-km-'+i);if(td)td.textContent='Calculating…';try{let r=await requestRoad(stops[i],stops[i+1]);td.textContent=dfloat(r.distanceKm)+' km road · '+Math.round(r.durationMin)+' min';}catch{if(td)td.textContent=dfloat(hav(stops[i],stops[i+1]))+' km straight-line only';}}};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-v2-road]');if(b){let i=Number(b.dataset.v2Road),td=$('#v2-km-'+i);td.textContent='Calculating…';try{let r=await requestRoad(stops[i],stops[i+1]);td.textContent=dfloat(r.distanceKm)+' km road · '+Math.round(r.durationMin)+' min';}catch(err){td.textContent=dfloat(hav(stops[i],stops[i+1]))+' km straight line; '+err.message}}const c=e.target.closest('[data-v2-choose]');if(c){$('#v2-select-next').value=c.dataset.v2Choose;drawSelectors();requestRoadFromGPS();}});
// Rail data: do not label schedule suggestions as real-time seat availability.
$('#v2-train-form').onsubmit=async e=>{e.preventDefault();const from=$('#v2-train-from').value.toUpperCase().trim(),to=$('#v2-train-to').value.toUpperCase().trim(),date=$('#v2-train-date').value,cls=$('#v2-train-class').value;const out=$('#v2-train-results'),status=$('#v2-train-status');if(!/^[A-Z0-9]{2,6}$/.test(from)||!/^[A-Z0-9]{2,6}$/.test(to))return notify('Use station codes such as NDLS and JAT.');out.innerHTML='';status.textContent='Checking connected train enquiry service…';try{const response=await fetch(`/api/trains?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}&date=${encodeURIComponent(date)}&class=${cls}`,{signal:AbortSignal.timeout(18000)}),j=await response.json();if(!response.ok)throw Error(j.error||'Provider error');if(j.status==='not_configured'){status.textContent='Live API not configured. Showing only matching PLANNED timetable entries; seat availability is unknown. Confirm on IRCTC / NTES.';const matches=DATA.trains.filter(t=>t.from.toUpperCase().startsWith(from)&&t.to.toUpperCase().startsWith(to));out.innerHTML=matches.length?matches.map(t=>`<div class="v2-item"><b>${h(t.number)} ${h(t.name)}</b><span class="v2-tag risk">Published plan · not live</span><div class="v2-muted">${h(t.from)} → ${h(t.to)} · ${h(t.note)}</div></div>`).join(''):'<div class="v2-item">No planned direct leg listed. Search official IRCTC for connecting trains and seat status.</div>';return}status.textContent=`External train provider: ${j.provider} · checked ${new Date(j.checkedAt).toLocaleTimeString('en-IN')} · NOT an IRCTC booking confirmation.`;out.innerHTML=(j.trains||[]).length?j.trains.map(t=>`<div class="v2-item"><div class="v2-between"><b>${h(t.number)} · ${h(t.name)}</b><span class="v2-tag blue">${h(t.availability||'Availability not supplied')}</span></div><div class="v2-muted">${h(t.departure||'Departure not supplied')} → ${h(t.arrival||'Arrival not supplied')} · ${h(t.duration||'Duration not supplied')} ${Number.isFinite(Number(t.distanceKm))&&t.distanceKm!==null?'· '+h(t.distanceKm)+' rail km (provider)':''}</div><button class="v2-toolbtn" data-v2-seat="${h(t.number)}">Check live seat availability</button></div>`).join(''):'<div class="v2-item">No train records returned. Confirm on official IRCTC.</div>'}catch(err){status.textContent='Live lookup failed: '+err.message+'. Use official links. No invented train availability.'}};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-v2-seat]');if(!el)return;const trainNo=el.dataset.v2Seat,from=$('#v2-train-from').value.toUpperCase().trim(),to=$('#v2-train-to').value.toUpperCase().trim(),date=$('#v2-train-date').value,cls=$('#v2-train-class').value;el.textContent='Checking…';try{let response=await fetch('/api/trains?'+new URLSearchParams({mode:'availability',trainNo,from,to,date,class:cls}));let j=await response.json();if(!response.ok)throw Error(j.error||'Provider error');let val=JSON.stringify(j.availability??{}).slice(0,650);el.insertAdjacentHTML('afterend','<div class="v2-muted">Provider seat response: '+h(val)+' · verify on IRCTC before booking.</div>')}catch(err){el.insertAdjacentHTML('afterend','<div class="v2-muted">Seat check unavailable: '+h(err.message)+'</div>')}finally{el.textContent='Recheck seats'}});
// Current 7-day weather and the live station board are optional provider functions.
$('#v2-weather-check').onclick=async()=>{let s=stops[Number($('#v2-select-next').value)],el=$('#v2-weather-info');if(!s)return;el.innerHTML='<div class="v2-item">Checking forecast…</div>';try{let r=await fetch('/api/weather?lat='+encodeURIComponent(s.lat)+'&lon='+encodeURIComponent(s.lng),{signal:AbortSignal.timeout(14000)}),d=await r.json();if(!r.ok)throw Error(d.error||'Weather service unavailable');const c=d.current||{},dd=d.daily||{},dates=dd.time||[];el.innerHTML=`<div class="v2-item"><span class="v2-tag blue">${h(s.name)}</span><h3>${h(c.temperature_2m??'—')}°C <span class="v2-muted">feels like ${h(c.apparent_temperature??'—')}°C</span></h3><div class="v2-muted">Wind ${h(c.wind_speed_10m??'—')} km/h · Current snowfall ${h(c.snowfall??'—')} cm</div></div>`+dates.map((dt,i)=>`<div class="v2-money-row"><b>${h(dt)}</b><span>${h(dd.temperature_2m_min?.[i]??'—')}°–${h(dd.temperature_2m_max?.[i]??'—')}°C · Snow ${h(dd.snowfall_sum?.[i]??'—')} cm · Precip. ${h(dd.precipitation_probability_max?.[i]??'—')}%</span></div>`).join('')}catch(err){el.innerHTML='<div class="v2-item">'+h(err.message)+' · use your official weather provider for winter warnings.</div>'}};
$('#v2-station-check').onclick=async()=>{let station=$('#v2-station-code').value.toUpperCase().trim()||$('#v2-train-from').value,el=$('#v2-station-result');if(!/^[A-Z0-9]{2,6}$/.test(station))return notify('Enter a station code.');el.innerHTML='<div class="v2-item">Checking live station board…</div>';try{let r=await fetch('/api/trains?mode=station&from='+encodeURIComponent(station)),d=await r.json();if(!r.ok)throw Error(d.error||'Unavailable');if(d.status==='not_configured')throw Error('Rail provider not configured; use official NTES');let raw=d.statusDetails?.trains||d.statusDetails?.data?.trains||d.statusDetails?.results||d.statusDetails||[];let list=Array.isArray(raw)?raw:[];el.innerHTML=list.slice(0,15).map(t=>`<div class="v2-item"><b>${h(t.train_number||t.trainNo||t.number||'')} ${h(t.train_name||t.trainName||t.name||'')}</b><div class="v2-muted">Time ${h(t.departure||t.departureTime||t.arrival||t.arrivalTime||'Check provider')} · Platform ${h(t.platform||t.platformNo||'unconfirmed')} · Delay ${h(t.delay||t.delayMinutes||'unconfirmed')}</div></div>`).join('')||'<div class="v2-item">Provider responded but no normalizable train board records; check NTES directly.</div>';}catch(err){el.innerHTML='<div class="v2-item">'+h(err.message)+'</div>'}};
// Booking records and local indexedDB ticket storage.
const fields=['type','status','title','train','date','from','to','depart','arrive','seat','fare','ref','notes'];
function bookingReset(){ $('#v2-booking-form').reset();$('#v2-book-id').value='';$('#v2-book-date').value='2027-01-14'}
$('#v2-book-clear').onclick=bookingReset;
$('#v2-booking-form').onsubmit=e=>{e.preventDefault();let record={id:$('#v2-book-id').value||uid()};for(const field of fields)record[field]=$('#v2-book-'+field).value.trim();if(!record.title)return;bookings=[record,...bookings.filter(x=>x.id!==record.id)];saveBookings();bookingReset();notify('Booking record saved locally.');};
function drawBookings(){const confirmed=bookings.filter(x=>x.status==='Booked'||x.status==='Completed').length;$('#v2-bookings-summary').innerHTML=`<div class="v2-item"><strong class="v2-statstrong">${confirmed}/${bookings.length}</strong> <span class="v2-muted">confirmed records</span></div><div class="v2-item">Trek reporting: <b>Jan 23 · 09:00 · Dehradun</b><br><small class="v2-muted">Keep departure and arrival buffers.</small></div>`;$('#v2-booking-list').innerHTML=bookings.length?bookings.map(x=>`<div class="v2-item v2-between"><div><span class="v2-tag ${x.status==='Booked'?'good':x.status==='Waitlisted'?'risk':'blue'}">${h(x.status)}</span> <b>${h(x.title)}</b><div class="v2-muted">${h(x.date)} · ${h(x.from||'—')} → ${h(x.to||'—')} · ${h(x.depart||'—')}–${h(x.arrive||'—')} · ${h(x.seat||'')}</div><div class="v2-tiny">${h(x.type)} · ${h(x.train)} · ${fmt(x.fare)} · ${h(x.notes)}</div></div><div class="v2-row"><button class="v2-toolbtn" data-v2-edit-book="${h(x.id)}">Edit</button><button class="v2-toolbtn" data-v2-del-book="${h(x.id)}">×</button>${x.train?`<button class="v2-toolbtn" data-v2-live-book="${h(x.id)}">Live</button>`:''}</div></div>`).join(''):'<p class="v2-muted">No bookings recorded. Import the planned trains as unchecked items, then mark actual bookings.</p>';$('#v2-ticket-id').innerHTML=bookings.map(x=>`<option value="${h(x.id)}">${h(x.title)}</option>`).join('')||'<option value="">Add a booking first</option>'}
$('#v2-seed-trains').onclick=()=>{if(!confirm('Add the published planned trains as unbooked records? You can edit all times and details.'))return;let created=0;for(const t of DATA.trains){if(bookings.some(b=>b.train===t.number&&b.date.startsWith('2027-'+({Jan:'01',Feb:'02'})[(t.date||'').split(' ')[1]])))continue;const date='2027-01-'+String(parseInt(t.date,10)).padStart(2,'0');bookings.push({id:uid(),type:'train',status:'Not booked',title:t.number+' '+t.name,train:t.number,date,from:(t.from.match(/^\w{2,5}/)||[])[0]||'',to:(t.to.match(/^\w{2,5}/)||[])[0]||'',depart:'',arrive:'',seat:'',fare:'0',ref:'',notes:t.from+' → '+t.to+'. '+t.note});created++}saveBookings();notify('Imported '+created+' planned trains; none marked as booked.')};
document.addEventListener('click',async e=>{let b=e.target.closest('[data-v2-edit-book]');if(b){let rec=bookings.find(x=>x.id===b.dataset.v2EditBook);if(!rec)return;$('#v2-book-id').value=rec.id;fields.forEach(f=>$('#v2-book-'+f).value=rec[f]||'');$('#v2-book-title').focus()}let del=e.target.closest('[data-v2-del-book]');if(del&&confirm('Delete this booking?')){bookings=bookings.filter(x=>x.id!==del.dataset.v2DelBook);saveBookings()}let live=e.target.closest('[data-v2-live-book]');if(live){let rec=bookings.find(x=>x.id===live.dataset.v2LiveBook);try{let response=await fetch('/api/trains?mode=running&trainNo='+encodeURIComponent(rec.train));let data=await response.json();notify(data.status==='not_configured'?'No live rail API configured. Open NTES for running status.':JSON.stringify(data.statusDetails||data).slice(0,250))}catch{notify('Live provider not connected. Use the NTES link in Train Search.')}}});
// IndexedDB file safe local storage (tickets, receipts, photos)
let idbPromise=null;function idb(){if(!('indexedDB' in window))return Promise.reject(Error('IndexedDB unavailable'));if(!idbPromise)idbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('northbound_secure_files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return idbPromise}
async function putFile(id,file){if(!file||file.size>5_000_000||!['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Use PDF, PNG, JPG or WEBP under 5 MB');let db=await idb();await new Promise((resolve,reject)=>{const t=db.transaction('files','readwrite'),r=t.objectStore('files').put({id,blob:file,name:file.name,type:file.type,createdAt:Date.now()});r.onsuccess=resolve;r.onerror=()=>reject(r.error)})}
async function getFile(id){let db=await idb();return new Promise((resolve,reject)=>{const t=db.transaction('files','readonly'),r=t.objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function viewBlob(record){if(!record)return notify('No file saved for this item.');let u=URL.createObjectURL(record.blob),a=document.createElement('a');a.href=u;a.target='_blank';a.rel='noopener';a.download=record.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000)}
$('#v2-ticket-save').onclick=async()=>{try{let id=$('#v2-ticket-id').value,file=$('#v2-ticket-file').files?.[0];if(!id)throw Error('Create a booking first');await putFile('ticket:'+id,file);notify('Ticket saved only on this device.')}catch(err){notify(err.message)}};
$('#v2-ticket-open').onclick=async()=>{try{viewBlob(await getFile('ticket:'+$('#v2-ticket-id').value))}catch(err){notify(err.message)}};
$('#v2-pnr-check').onclick=async()=>{const id=$('#v2-ticket-id').value,b=bookings.find(b=>b.id===id),pnr=b?.ref;if(!pnr||!/^\d{10}$/.test(pnr))return notify('Store a 10-digit PNR in this booking first.');if(!confirm('Send this PNR to your configured THIRD-PARTY railway API for verification? PNR details may contain personal information.'))return;let el=$('#v2-pnr-result');el.textContent='Checking PNR…';try{let r=await fetch('/api/pnr',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({pnr})}),d=await r.json();if(!r.ok)throw Error(d.error||'PNR provider error');el.textContent=d.status==='not_configured'?d.message:'Provider response: '+JSON.stringify(d.details).slice(0,1000)}catch(err){el.textContent=err.message}};

// Expense receipt attachment and editing
function expControls(){let data=window.NB?.get()?.expenses||getOld('expenses',[]);const sel=$('#v2-receipt-expense');if(sel){const value=sel.value;sel.innerHTML=data.map(e=>`<option value="${h(e.id)}">${h(e.date)} · ${h(e.description)} · ${fmt(e.amount)}</option>`).join('')||'<option value="">No expenses</option>';if(data.some(e=>e.id===value))sel.value=value}let edit=$('#v2-edit-expense');if(edit){const val=edit.value;edit.innerHTML=data.map(e=>`<option value="${h(e.id)}">${h(e.date)} · ${h(e.description)}</option>`).join('')||'<option>No expenses</option>';if(data.some(e=>e.id===val))edit.value=val;}}
$('#v2-receipt-save').onclick=async()=>{try{let id=$('#v2-receipt-expense').value;if(!id)throw Error('Add an expense first');await putFile('expense:'+id,$('#v2-receipt-file').files?.[0]);notify('Receipt securely stored on this device.')}catch(err){notify(err.message)}};
$('#v2-receipt-open').onclick=async()=>{try{viewBlob(await getFile('expense:'+$('#v2-receipt-expense').value))}catch(err){notify(err.message)}};
$('#v2-edit-expense-btn').onclick=()=>{let id=$('#v2-edit-expense').value,e=(window.NB?.get()?.expenses||[]).find(x=>x.id===id);if(!e)return notify('Select an expense');$('#v2-exp-edit-value').value=e.amount;$('#v2-exp-edit-desc').value=e.description;};
$('#v2-edit-expense-save').onclick=()=>{let id=$('#v2-edit-expense').value,state=window.NB?.get(),e=state?.expenses.find(x=>x.id===id);if(!e)return notify('Select an expense');let amount=Number($('#v2-exp-edit-value').value),desc=$('#v2-exp-edit-desc').value.trim();if(!(amount>0&&amount<=10000000&&desc))return notify('Enter a valid amount and description');let ns=Object.keys(e.shares),old=Number(e.amount);let shares={};let used=0;ns.forEach((n,i)=>{shares[n]=i===ns.length-1?Number((amount-used).toFixed(2)):Number((amount*e.shares[n]/old).toFixed(2));used+=shares[n]});e.amount=Number(amount.toFixed(2));e.description=desc;e.shares=shares;window.NB?.importRemote({...state,expenses:state.expenses});window.dispatchEvent(new CustomEvent('nb:update',{detail:{key:'expenses',value:state.expenses}}));notify('Expense corrected; share amounts recalculated.')};
// Settle real payments, display per-member spending and daily report
function settlementControls(){let members=window.NB?.get()?.members||getOld('members',['You']);let opts=members.map(m=>`<option value="${h(m)}">${h(m)}</option>`).join('');['v2-settle-from','v2-settle-to'].forEach(id=>{let sel=$('#'+id),v=sel.value;sel.innerHTML=opts;if(members.includes(v))sel.value=v});}
$('#v2-settlement-form').onsubmit=e=>{e.preventDefault();let from=$('#v2-settle-from').value,to=$('#v2-settle-to').value,amt=Number($('#v2-settle-amt').value);if(!from||!to||from===to||!(amt>0))return notify('Choose different people and a positive amount');payments.push({id:uid(),date:dateNow(),from,to,amount:Number(amt.toFixed(2)),method:$('#v2-settle-method').value});write('payments',payments);e.target.reset();drawPayments();window.NB?.renderSplit();notify('Repayment logged. Mark both people as having confirmed it.')};
