function drawAnalytics(){let data=window.NB?.get()?.expenses||getOld('expenses',[]),byday={},byPerson={},total=0;for(const e of data){total+=Number(e.amount)||0;byday[e.date]=(byday[e.date]||0)+Number(e.amount||0);byPerson[e.payer]=(byPerson[e.payer]||0)+Number(e.amount||0)}let budget=window.NB?.get()?.budgets||getOld('budgets',DATA.budgets),max=Object.values(byday).reduce((a,b)=>Math.max(a,b),1);$('#v2-analytics').innerHTML=`<div class="v2-item">${fmt(total)} spent over ${Object.keys(byday).length} expense days · average ${fmt(Object.keys(byday).length?total/Object.keys(byday).length:0)} per spending day</div>`+Object.keys(byday).sort().map(d=>`<div class="v2-money-row"><span>${h(d)}</span><div style="flex:1;max-width:190px"><div class="v2-progress"><div style="width:${byday[d]/max*100}%"></div></div></div><b>${fmt(byday[d])}</b></div>`).join('');$('#v2-top-payers').innerHTML=Object.entries(byPerson).sort((a,b)=>b[1]-a[1]).map(([n,a])=>`<div class="v2-money-row"><b>${h(n)}</b><span>${fmt(a)}</span></div>`).join('')||'<p class="v2-muted">Record expenses to see contributors.</p>'}
const csvValue=s=>'"'+String(s??'').replace(/"/g,'""')+'"';function download(name,text,type='text/plain'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#v2-analytics-export').onclick=()=>{let data=window.NB?.get()?.expenses||getOld('expenses',[]),byday={};for(let e of data)byday[e.date]=(byday[e.date]||0)+Number(e.amount);download('northbound-daily-spending.csv','Date,Amount INR\r\n'+Object.keys(byday).sort().map(k=>[k,byday[k]].map(csvValue).join(',')).join('\r\n'),'text/csv')};
// Intelligent transparent rules, no online model dependency
const criticalSet=['16367','12401','12402','26401','26402','12626'];
function drawCoach(){let b=window.NB?.get()||{expenses:getOld('expenses',[]),budgets:getOld('budgets',DATA.budgets),checks:getOld('checks',{})},booked=bookings.filter(x=>x.status==='Booked'||x.status==='Completed'),criticalBooked=criticalSet.filter(n=>booked.some(x=>x.train===n)).length,budget=Object.values(b.budgets).reduce((a,n)=>a+Number(n||0),0),spent=b.expenses.reduce((a,x)=>a+Number(x.amount||0),0),ready=Math.min(100,Math.round(criticalBooked/criticalSet.length*65+Object.values(b.checks||{}).filter(Boolean).length/16*35));$('#v2-readiness').textContent=ready+'%';$('#v2-readiness-bar').style.width=ready+'%';$('#v2-readiness-caption').textContent=criticalBooked+'/'+criticalSet.length+' critical trains entered as booked; checklist items add readiness.';$('#v2-coach-money').textContent=fmt(budget-spent);$('#v2-coach-spending').textContent=spent>budget?'Over the planned budget — reduce non-essential expenses.':'Remaining from '+fmt(budget)+' planned budget.';let days=Math.ceil((Date.parse('2027-01-14T20:55:00+05:30')-Date.now())/86400000);$('#v2-countdown').textContent=days>0?days+' days':days===0?'Departure day':'Trip has started / ended';let tips=[{type:'risk',title:'Protect your fixed 9 AM trek reporting',text:'Nanda Devi scheduled 05:50 arrival leaves ~3 hours. Confirm your exact pickup location and a backup road transfer. Never gamble on an unprotected late train.'},{type:'risk',title:'January 27 trek return could run late',text:'The 22:45 Dehradun train depends on winter-road conditions and when your trek vehicle returns. Ask the operator for realistic worst-case timing and a backup.'},{type:'risk',title:'Gulmarg skiing is a short winter window',text:'Plan the instructor, rental, Srinagar ↔ Gulmarg road trip and one heated room. Road closures and gondola cancellations can erase the session.'},{type:'risk',title:'Your Kashmir trains have narrow margins',text:'Jammu arrival around 05:00 to a 06:20 Vande Bharat is a risky connection. Research an afternoon backup; avoid claiming seats are confirmed.'},{type:'risk',title:'February 2 return has almost no delay buffer',text:'Kerala Express is planned to arrive late in the evening. If the return deadline is absolute, secure a backup route or depart sooner.'}];if(criticalBooked<criticalSet.length)tips.unshift({type:'risk',title:'Book critical sleeper and chair-car seats',text:criticalBooked+'/'+criticalSet.length+' priority trains recorded as booked. Open the Bookings tab and record PNR, date, coach and verified status.'});if(spent>budget*.8&&budget)tips.push({type:spent>budget?'bad':'risk',title:'Reduce remaining spending',text:fmt(spent)+' used out of '+fmt(budget)+'. Keep an emergency fund for Kashmir and long train delays.'});if(stops.some(s=>s.key==='custom'))tips.push({type:'blue',title:'Check newly added destination transfers',text:'You have custom stops. Use Connections to confirm distance and onward trains before committing.'});if(!bookings.some(b=>b.type==='ski'&&b.status==='Booked'))tips.push({type:'blue',title:'Prearrange a beginner ski lesson',text:'Reserve an instructor, helmet and rental equipment in Gulmarg; avoid unguided slopes.'});if(!bookings.some(b=>b.type==='stay'&&b.status==='Booked'))tips.push({type:'blue',title:'One heated room remains unbooked',text:'You have eliminated dorms, but a heated Kashmir room is safer than overnight winter road travel.'});$('#v2-tips').innerHTML=tips.map(x=>`<div class="v2-item"><span class="v2-tag ${x.type}">${x.type==='risk'?'Needs attention':x.type==='bad'?'Over budget':'Improvement'}</span><h4 style="margin:9px 0">${h(x.title)}</h4><p style="margin:0">${h(x.text)}</p></div>`).join('');}
$('#v2-idea-form').onsubmit=e=>{e.preventDefault();let body=$('#v2-idea').value.trim();if(!body)return;ideas.push({id:uid(),text:body,createdAt:dateNow(),done:false});write('ideas',ideas);e.target.reset();drawIdeas()};function drawIdeas(){$('#v2-ideas').innerHTML=ideas.map(x=>`<div class="v2-item v2-between"><span>${x.done?'✅ ':''}${h(x.text)}</span><div class="v2-row"><button class="v2-toolbtn" data-v2-idea-done="${h(x.id)}">✓</button><button class="v2-toolbtn" data-v2-idea-del="${h(x.id)}">×</button></div></div>`).join('')||'<p class="v2-muted">Your improvement backlog is empty.</p>'}
document.addEventListener('click',e=>{let d=e.target.closest('[data-v2-idea-done]'),del=e.target.closest('[data-v2-idea-del]');if(d){let x=ideas.find(x=>x.id===d.dataset.v2IdeaDone);if(x)x.done=!x.done;write('ideas',ideas);drawIdeas()}if(del){ideas=ideas.filter(x=>x.id!==del.dataset.v2IdeaDel);write('ideas',ideas);drawIdeas()}});
$('#v2-emergency-form').onsubmit=e=>{e.preventDefault();emergency={name:$('#v2-emergency-name').value.trim().slice(0,60),phone:$('#v2-emergency-phone').value.trim().slice(0,25)};write('emergency',emergency);drawEmergency();notify('Contact saved in browser')};function drawEmergency(){$('#v2-emergency-name').value=emergency.name||'';$('#v2-emergency-phone').value=emergency.phone||'';$('#v2-emergency-preview').innerHTML=emergency.phone?`<a class="btn small" href="tel:${h(emergency.phone.replace(/[^+\d]/g,''))}">Call ${h(emergency.name||'emergency contact')} · ${h(emergency.phone)}</a>`:'<p class="v2-muted">Add a contact for quick access.</p>'}
